import struct, sys

# ---------------- FFmpeg av_crc port (validate against static tables) ----------------
def bswap32(c):
    return struct.unpack(">I", struct.pack("<I", c & 0xFFFFFFFF))[0]

def av_crc_init(le, bits, poly):
    ctx = [0]*257
    for i in range(256):
        if le:
            c = i
            for _ in range(8):
                c = (c >> 1) ^ (poly if (c & 1) else 0)
            ctx[i] = c & 0xFFFFFFFF
        else:
            c = (i << 24) & 0xFFFFFFFF
            for _ in range(8):
                mask = 0xFFFFFFFF if (c & 0x80000000) else 0
                c = ((c << 1) & 0xFFFFFFFF) ^ (((poly << (32 - bits)) & 0xFFFFFFFF) & mask)
            ctx[i] = bswap32(c)
    ctx[256] = 1
    return ctx

def av_crc(ctx, crc, data):
    crc &= 0xFFFFFFFF
    for b in data:
        crc = (ctx[((crc & 0xFF) ^ b)] ^ (crc >> 8)) & 0xFFFFFFFF
    return crc

# Validate against AV_CRC_16_ANSI static table from crc.c
