def ff_mlp_checksum16(buf):
    # buf_size = header_size - 2 ; av_crc over first (buf_size-2), xor RL16 at buf_size-2
    n = len(buf)
    crc = av_crc(crc_2D, 0, buf[:n-2])
    crc ^= struct.unpack('<H', buf[n-2:n])[0]
    return crc & 0xFFFF

def ff_mlp_calculate_parity(buf):
    scratch = 0
    for b in buf:
        scratch ^= b
    scratch ^= (scratch >> 16)
    scratch ^= (scratch >> 8)
    return scratch & 0xFF

def ff_mlp_checksum8(buf):
    n = len(buf)
    c = av_crc(crc_63, 0x3c, buf[:n-1])
    c ^= buf[n-1]
    return c & 0xFF

def ff_mlp_restart_checksum(buf, bit_size):
    num_bytes = (bit_size + 2)//8
    crc = crc_1D[buf[0] & 0x3f]
    crc = av_crc(crc_1D, crc, buf[1:num_bytes-1])
    crc ^= buf[num_bytes-1]
    for i in range((bit_size+2) & 7):
        crc <<= 1
        if crc & 0x100: crc ^= 0x11D
        crc ^= (buf[num_bytes] >> (7 - i)) & 1
        crc &= 0x1FF
    return crc & 0xFF

# ---------------- Bit writer (MSB-first) ----------------
class BitWriter:
    def __init__(self):
        self.bits = []
    def put(self, value, nbits):
        for i in range(nbits-1, -1, -1):
            self.bits.append((value >> i) & 1)
    def align(self):
        while len(self.bits) % 8:
            self.bits.append(0)
    def bytes(self):
        self.align()
        out = bytearray()
        for i in range(0, len(self.bits), 8):
            byte = 0
            for b in self.bits[i:i+8]:
                byte = (byte << 1) | b
            out.append(byte)
        return bytes(out)
    def nbits(self):
        return len(self.bits)

